mapper.sql:
WHERE rsd.camp_id = #{campId}
  AND rsd.biz_date >= #{startDate}
  AND rsd.biz_date < #{endDate}

    AND rsd.room_category_id IN

        #{roomCategoryId}



    AND rsd.poi_id IN

        #{poiId}



    AND EXISTS (
        SELECT 1
        FROM room_category rc
        WHERE rc.room_category_id = rsd.room_category_id
          AND rc.camp_id = rsd.camp_id
          AND rc.name LIKE CONCAT('%', #{keyword}, '%')
    )

WHERE om.camp_id = #{campId} AND om.is_deleted = 0 AND om.start_at < #{endDate} AND om.end_at > #{startDate} AND om.status NOT IN ('cancelled', 'canceled') AND om.room_category_id IS NOT NULL AND om.room_id IS NOT NULL
AND om.room_category_id IN
#{roomCategoryId}
AND om.poi_id IN
#{poiId}
AND ( om.guest_name LIKE CONCAT('%', #{keyword}, '%') OR EXISTS ( SELECT 1 FROM room r WHERE r.room_id = om.room_id AND r.camp_id = om.camp_id AND r.room_name LIKE CONCAT('%', #{keyword}, '%') ) OR EXISTS ( SELECT 1 FROM room_category rc WHERE rc.room_category_id = om.room_category_id AND rc.camp_id = om.camp_id AND rc.name LIKE CONCAT('%', #{keyword}, '%') ) )
